import {
	Card,
	CardAction,
	CardDescription,
	CardHeader,
	CardTitle,
} from "@mizen-labs/ui";
import { Badge } from "@mizen-labs/ui/badge";
import { Inline } from "@mizen-labs/ui/inline";
import { Stack } from "@mizen-labs/ui/stack";
import { SpecimenSection } from "./specimen-section";

const variantSamples = [
	{ label: "Queued", variant: "default" },
	{ label: "Failed", variant: "destructive" },
	{ label: "In review", variant: "info" },
	{ label: "Draft", variant: "outline" },
	{ label: "Archived", variant: "secondary" },
	{ label: "Synced", variant: "success" },
	{ label: "Needs review", variant: "warning" },
	{ label: "Featured", variant: "brand" },
] as const;

const statusSamples = [
	{ label: "Delivery failed", variant: "destructive" },
	{ label: "Processing", variant: "info" },
	{ label: "Delivered", variant: "success" },
	{ label: "Waiting", variant: "warning" },
] as const;

const sizeSamples = [
	{ label: "Unread", size: "sm" },
	{ label: "In progress", size: "default" },
	{ label: "Featured", size: "lg" },
] as const;

export function BadgeSpecimen() {
	return (
		<Stack gap="8">
			<Card>
				<CardHeader>
					<CardTitle>Autumn launch</CardTitle>
					<CardDescription>Product team · Release review</CardDescription>
					<CardAction>
						<Badge variant="info">In review</Badge>
					</CardAction>
				</CardHeader>
			</Card>
			<SpecimenSection
				description="Use badges to make compact status and category values scannable."
				title="Semantic variants"
			>
				<Inline>
					{variantSamples.map(({ label, variant }) => (
						<Badge key={variant} variant={variant}>
							{label}
						</Badge>
					))}
				</Inline>
			</SpecimenSection>
			<SpecimenSection
				description="Fill a status badge with its color where statuses must stand out in a dense table or list."
				title="Soft status"
			>
				<Inline>
					{statusSamples.map(({ label, variant }) => (
						<Badge appearance="soft" key={variant} variant={variant}>
							{label}
						</Badge>
					))}
				</Inline>
			</SpecimenSection>
			<SpecimenSection title="Sizes">
				<Inline>
					{sizeSamples.map(({ label, size }) => (
						<Badge key={size} size={size}>
							{label}
						</Badge>
					))}
				</Inline>
			</SpecimenSection>
			<SpecimenSection
				description="Render a badge as a link when the status needs a destination."
				title="Polymorphic link"
