"use client";

import { props, create } from "@stylexjs/stylex";

import { colors } from "@mizen-labs/ui/colors.stylex";

import { space } from "@mizen-labs/ui/spacing.stylex";

import {
	fontSize,
	fontWeight,
	lineHeight,
} from "@mizen-labs/ui/typography.stylex";

import type {
	FileRejection,
	FileRejectionCode,
	FileUploadChangeDetails,
	FileUploadDropzoneState,
	FileUploadStatus,
} from "@mizen-labs/ui";

import {
	FileUpload,
	FileUploadDropzone,
	FileUploadInput,
	FileUploadItem,
	FileUploadList,
	Stack,
	Text,
	Button,
	FileUploadItemName,
	FileUploadItemPreview,
	FileUploadItemProgress,
	FileUploadItemRemove,
	FileUploadItemSize,
	FileUploadItemStatus,
	FileUploadTrigger,
} from "@mizen-labs/ui";

import { useCallback, useRef, useState } from "react";

import {
	IconAlertCircle,
	IconUpload,
	IconFileCode,
	IconFileSpreadsheet,
	IconFileText,
	IconPresentation,
	IconVideo,
} from "@tabler/icons-react";

import type { MouseEvent } from "react";

const uploadPreviewStyles = create({
	actions: {
		alignItems: "center",
		display: "flex",
		flexDirection: "column",
		flexShrink: 0,
		gap: space["1"],
	},
	copy: {
		display: "flex",
		flexBasis: "12rem",
		flexDirection: "column",
		flexGrow: 1,
		minInlineSize: 0,
	},
	detail: {
		alignItems: "center",
		display: "flex",
		flexWrap: "wrap",
		gap: space["2"],
		justifyContent: "flex-start",
	},
	header: {
		alignItems: "center",
		display: "flex",
		gap: space["3"],
		inlineSize: "100%",
		minInlineSize: 0,
	},
	icon: {
		color: colors.brandForeground,
		display: "flex",
		flexShrink: 0,
		// The icon lifts while files hover over the drop row.
		transform: {
			":is([data-dragging] *)": "translateY(-0.1875rem)",
			default: "none",
		},
		transitionDuration: {
			"@media (prefers-reduced-motion: reduce)": "0ms",
			default: "240ms",
		},
		transitionProperty: "transform",
		transitionTimingFunction: "cubic-bezier(0.34, 1.56, 0.64, 1)",
	},
	limits: {
		color: colors.mutedContent,
		fontSize: fontSize["14"],
		lineHeight: lineHeight["20"],
		margin: 0,
	},
	limitsError: { color: colors.destructive },
	metadata: {
		alignItems: "flex-start",
		display: "flex",
		flexDirection: "column",
		flexGrow: 1,
		gap: space["1"],
		minInlineSize: 0,
	},
	percentage: {
		color: colors.secondaryContent,
		fontSize: fontSize["12"],
		fontVariantNumeric: "tabular-nums",
		lineHeight: lineHeight["16"],
	},
	percentageDisabled: { color: colors.secondaryContent },
	percentageError: { color: colors.destructive },
	percentageSuccess: { color: colors.successContent },
	// The line folds away once the upload finishes; the gap above folds with it.
	progressClip: { minBlockSize: 0, overflow: "hidden" },
	progressSlot: {
		display: "grid",
		gridTemplateRows: "1fr",
		inlineSize: "100%",
		marginBlockStart: 0,
		opacity: 1,
		transitionDuration: {
			"@media (prefers-reduced-motion: reduce)": "0ms",
			default: "320ms",
		},
		transitionProperty: "grid-template-rows, margin-block-start, opacity",
		transitionTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)",
	},
	progressSlotDone: {
		gridTemplateRows: "0fr",
		marginBlockStart: `calc(-1 * ${space["2"]})`,
		opacity: 0,
	},
	rejectIcon: { color: colors.destructive, flexShrink: 0 },
	root: {
		inlineSize: "100%",
		marginInline: "auto",
		maxInlineSize: "32rem",
		minInlineSize: 0,
	},
	title: {
		color: colors.content,
		fontSize: fontSize["14"],
		fontWeight: fontWeight.medium,
		lineHeight: lineHeight["20"],
		margin: 0,
	},
	upload: {
		alignItems: "center",
		display: "flex",
		flexDirection: "column",
		gap: space["2"],
		inlineSize: "100%",
		minInlineSize: 0,
	},
});

const fileTypeIconStyles = create({
	code: { color: colors.chartSeries6 },
	document: { color: colors.brandForeground },
	presentation: { color: colors.chartSeries2 },
	spreadsheet: { color: colors.chartSeries3 },
	video: { color: colors.chartSeries5 },
});

const FILE_EXTENSION = /\.(?<extension>[^.]+)$/u;

const fileKinds = [
	{
		extension: /^(?:csv|tsv|xls|xlsx|xlsm|ods|numbers)$/u,
		kind: "spreadsheet",
		mime: /spreadsheet|excel|text\/(?:csv|tab-separated-values)/u,
	},
	{
		extension: /^(?:ppt|pptx|pps|ppsx|odp|key)$/u,
		kind: "presentation",
		mime: /presentation|powerpoint|keynote/u,
	},
	{
		extension:
			/^(?:js|jsx|ts|tsx|mjs|cjs|json|html|css|scss|xml|py|rb|rs|go|java|c|cpp|h|cs|sh|sql|yaml|yml|toml)$/u,
		kind: "code",
		mime: /^(?:application|text)\/(?:x-)?(?:javascript|typescript|json|xml|html|css|python|shellscript)(?:;|$)/u,
	},
	{
		extension: /^(?:mp4|webm|mov|m4v|avi|mkv|mpeg|mpg|ogv)$/u,
		kind: "video",
		mime: /^video\//u,
	},
] as const;

const icons = {
	code: IconFileCode,
	document: IconFileText,
	presentation: IconPresentation,
	spreadsheet: IconFileSpreadsheet,
	video: IconVideo,
};

function getFileKind(file: Pick<File, "name" | "type">) {
	const extension = file.name.match(FILE_EXTENSION)?.[1].toLowerCase() ?? "";
	const mime = file.type.toLowerCase();
	return (
		(
			fileKinds.find((rule) => rule.mime.test(mime)) ??
			fileKinds.find((rule) => rule.extension.test(extension))
		)?.kind ?? "document"
	);
}

function FileTypeIcon({ file }: { file: Pick<File, "name" | "type"> }) {
	const kind = getFileKind(file);
	const Icon = icons[kind];
	return (
		<Icon
			aria-hidden="true"
			data-file-kind={kind}
			size={24}
			stroke={1.5}
			{...props(fileTypeIconStyles[kind])}
		/>
	);
}

function promptTitle({ dragCount, isDragging }: FileUploadDropzoneState) {
	if (!isDragging) {
		return "Drop files here";
	}
	if (dragCount === 0) {
		return "Release to add files";
	}
	return `Drop ${dragCount} ${dragCount === 1 ? "file" : "files"}`;
}

function FileUploadPrompt({
	error,
	state,
	triggerTestId,
}: {
	error?: string;
	state: FileUploadDropzoneState;
	triggerTestId?: string;
}) {
	const Icon = error ? IconAlertCircle : IconUpload;
	return (
		<>
			<span
				aria-hidden="true"
				{...props(
					uploadPreviewStyles.icon,
					Boolean(error) && uploadPreviewStyles.rejectIcon
				)}
			>
				<Icon size={20} stroke={1.75} />
			</span>
			<div {...props(uploadPreviewStyles.copy)}>
				<p {...props(uploadPreviewStyles.title)}>{promptTitle(state)}</p>
				<p
					aria-live="polite"
					{...props(
						uploadPreviewStyles.limits,
						Boolean(error) && uploadPreviewStyles.limitsError
					)}
				>
					{error ?? "Images or PDF up to 5 MB (maximum 3 files)"}
				</p>
			</div>
			<FileUploadTrigger data-testid={triggerTestId}>
				Choose files
			</FileUploadTrigger>
		</>
	);
}

function uploadStatus(
	simulate: boolean,
	failed: boolean,
	progress: number,
	disabled?: boolean
): { status: FileUploadStatus; label: string } {
	if (disabled) {
		return { label: "Upload disabled", status: "pending" };
	}
	if (!simulate) {
		return { label: "Ready to upload", status: "pending" };
	}
	if (failed) {
		return { label: "Upload failed", status: "error" };
	}
	if (progress === 100) {
		return { label: "Uploaded", status: "success" };
	}
	return { label: "Uploading", status: "uploading" };
}

function FileUploadRow({
	file,
	simulate = false,
	failFirstAttempt,
	disabled,
}: {
	file: File;
	simulate?: boolean;
	failFirstAttempt?: boolean;
	disabled?: boolean;
}) {
	const [progress, setProgress] = useState(0);
	const progressRef = useRef(0);
	const [failed, setFailed] = useState(false);
	const [attempt, setAttempt] = useState(0);
	const startSimulation = useCallback(
		(node: HTMLDivElement | null) => {
			if (!(node && simulate) || disabled || failed) {
				return;
			}
			const timer = window.setInterval(() => {
				progressRef.current = Math.min(100, progressRef.current + 5);
				setProgress(progressRef.current);
				if (failFirstAttempt && attempt === 0 && progressRef.current === 40) {
					setFailed(true);
					window.clearInterval(timer);
				}
				if (progressRef.current === 100) {
					window.clearInterval(timer);
				}
			}, 200);
			return () => window.clearInterval(timer);
		},
		[simulate, disabled, failFirstAttempt, attempt, failed]
	);
	const retry = useCallback((event: MouseEvent<HTMLButtonElement>) => {
		event.currentTarget
			.closest('[data-slot="file-upload-item"]')
			?.querySelector<HTMLButtonElement>(
				'[data-slot="file-upload-item-remove"]'
			)
			?.focus();
		progressRef.current = 0;
		setProgress(0);
		setFailed(false);
		setAttempt((value) => value + 1);
	}, []);
	const { status, label } = uploadStatus(simulate, failed, progress, disabled);
	return (
		<div ref={startSimulation} {...props(uploadPreviewStyles.upload)}>
			<div {...props(uploadPreviewStyles.header)}>
				<FileUploadItemPreview>
					<FileTypeIcon file={file} />
				</FileUploadItemPreview>
				<div {...props(uploadPreviewStyles.metadata)}>
					<FileUploadItemName />
					<div {...props(uploadPreviewStyles.detail)}>
						<FileUploadItemSize />
						<FileUploadItemStatus status={status}>{label}</FileUploadItemStatus>
					</div>
				</div>
