	failed: boolean,
	progress: number,
	disabled?: boolean
): { status: FileUploadStatus; label: string } {
	if (disabled) {
		return { label: "Upload disabled", status: "pending" };
	}
	if (!simulate) {
		return { label: "Ready to upload", status: "pending" };
	}
	if (failed) {
		return { label: "Upload failed", status: "error" };
	}
	if (progress === 100) {
		return { label: "Uploaded", status: "success" };
	}
	return { label: "Uploading", status: "uploading" };
}

function FileUploadRow({
	file,
	simulate = false,
	failFirstAttempt,
	disabled,
}: {
	file: File;
	simulate?: boolean;
	failFirstAttempt?: boolean;
	disabled?: boolean;
}) {
	const [progress, setProgress] = useState(0);
	const progressRef = useRef(0);
	const [failed, setFailed] = useState(false);
	const [attempt, setAttempt] = useState(0);
	const startSimulation = useCallback(
		(node: HTMLDivElement | null) => {
			if (!(node && simulate) || disabled || failed) {
				return;
			}
			const timer = window.setInterval(() => {
				progressRef.current = Math.min(100, progressRef.current + 5);
				setProgress(progressRef.current);
				if (failFirstAttempt && attempt === 0 && progressRef.current === 40) {
					setFailed(true);
					window.clearInterval(timer);
				}
				if (progressRef.current === 100) {
					window.clearInterval(timer);
				}
			}, 200);
			return () => window.clearInterval(timer);
		},
		[simulate, disabled, failFirstAttempt, attempt, failed]
	);
	const retry = useCallback((event: MouseEvent<HTMLButtonElement>) => {
		event.currentTarget
			.closest('[data-slot="file-upload-item"]')
			?.querySelector<HTMLButtonElement>(
				'[data-slot="file-upload-item-remove"]'
			)
			?.focus();
		progressRef.current = 0;
		setProgress(0);
		setFailed(false);
		setAttempt((value) => value + 1);
	}, []);
	const { status, label } = uploadStatus(simulate, failed, progress, disabled);
	return (
		<div ref={startSimulation} {...props(uploadPreviewStyles.upload)}>
			<div {...props(uploadPreviewStyles.header)}>
				<FileUploadItemPreview>
					<FileTypeIcon file={file} />
				</FileUploadItemPreview>
				<div {...props(uploadPreviewStyles.metadata)}>
					<FileUploadItemName />
					<div {...props(uploadPreviewStyles.detail)}>
						<FileUploadItemSize />
						<FileUploadItemStatus status={status}>{label}</FileUploadItemStatus>
					</div>
				</div>
				<div {...props(uploadPreviewStyles.actions)}>
					<FileUploadItemRemove />
					{simulate ? (
						<span
							{...props(
								uploadPreviewStyles.percentage,
								failed && uploadPreviewStyles.percentageError,
								progress === 100 && uploadPreviewStyles.percentageSuccess,
								disabled && uploadPreviewStyles.percentageDisabled
							)}
						>
							{progress}%
						</span>
					) : null}
				</div>
			</div>
			{failed ? (
				<>
					<div role="alert">
						<Text size="ui" tone="muted">
							Connection lost. Try uploading this file again.
						</Text>
					</div>
					<Button disabled={disabled} onClick={retry} variant="outline">
						Retry upload
					</Button>
				</>
			) : null}
			{simulate ? (
				<div
					{...props(
						uploadPreviewStyles.progressSlot,
						progress === 100 && uploadPreviewStyles.progressSlotDone
					)}
				>
					<div {...props(uploadPreviewStyles.progressClip)}>
						<FileUploadItemProgress value={progress} />
					</div>
				</div>
			) : null}
		</div>
	);
}

const MAX_FILE_SIZE_BYTES = 5 * 1024 * 1024;

const REJECTION_MESSAGES = {
	"file-invalid-type": (name) => `${name} isn't an image or PDF.`,
	"file-too-large": (name) => `${name} is over 5 MB.`,
	"too-many-files": (name) => `${name} wasn't added. The limit is 3 files.`,
} satisfies Record<FileRejectionCode, (name: string) => string>;

function rejectionMessage(rejections: readonly FileRejection[]) {
	const [first, ...rest] = rejections;
	if (!first) {
		return;
	}
	const message = REJECTION_MESSAGES[first.code](first.file.name);
	if (rest.length === 0) {
		return message;
	}
	return `${message} ${rest.length} more ${rest.length === 1 ? "file was" : "files were"} skipped.`;
}

function FileUploadDragAndDropFilesHereExample1({
	testHooks = true,
	disabled,
	failFirstAttempt,
}: {
	testHooks?: boolean;
	disabled?: boolean;
	failFirstAttempt?: boolean;
}) {
	const hooks = testHooks
		? {
				dropzone: "file-upload-dropzone",
				list: "file-upload-list",
				root: "file-upload-specimen",
				trigger: "file-upload-trigger",
			}
		: {};
	const fileKeys = useRef(new WeakMap<File, string>());
	const keyForFile = useCallback((file: File) => {
		const existing = fileKeys.current.get(file);
		if (existing) {
			return existing;
		}
		const key = crypto.randomUUID();
		fileKeys.current.set(file, key);
		return key;
	}, []);
	const [rejections, setRejections] = useState<readonly FileRejection[]>([]);
	const [files, setFiles] = useState<readonly File[]>([]);
	const handleFileReject = useCallback((rejected: FileRejection[]) => {
		setRejections(rejected);
	}, []);
	const handleValueChange = useCallback(
		(nextFiles: readonly File[], details: FileUploadChangeDetails) => {
			setFiles(nextFiles);
			if (details.reason === "remove" || details.rejected.length === 0) {
				setRejections([]);
			}
		},
		[]
	);
	return (
		<FileUpload
			accept="image/*,.png,.jpg,.jpeg,.gif,.webp,.heic,.avif,.pdf"
			data-testid={hooks.root}
			disabled={disabled}
			maxFiles={3}
			maxSize={MAX_FILE_SIZE_BYTES}
			onFileReject={handleFileReject}
			onValueChange={handleValueChange}
			value={files}
		>
			<Stack gap="3">
				<FileUploadDropzone data-testid={hooks.dropzone}>
					{(state) => (
						<FileUploadPrompt
							error={rejectionMessage(rejections)}
							state={state}
							triggerTestId={hooks.trigger}
						/>
					)}
				</FileUploadDropzone>
				<FileUploadInput />

				<FileUploadList data-testid={hooks.list}>
					{(file, index) => (
						<FileUploadItem
							file={file}
							index={index}
							key={keyForFile(file)}
							layout="upload"
						>
							<FileUploadRow
								disabled={disabled}
								failFirstAttempt={failFirstAttempt}
								file={file}
								simulate={!testHooks}
							/>
						</FileUploadItem>
					)}
				</FileUploadList>

				{testHooks ? (
					<Text size="ui" tone="muted">
						Files stay in this browser example; no upload starts.
					</Text>
				) : null}
			</Stack>
		</FileUpload>
	);
}

export function FileUploadRetryExample() {
	return (
		<div {...props(uploadPreviewStyles.root)}>
			<FileUploadDragAndDropFilesHereExample1
				failFirstAttempt
				testHooks={false}
			/>
		</div>
	);
}

