		value: "18,240",
	},
	// Twelve weeks, starting the first Monday of September.
	Weekly: {
		delta: -0.098,
		label: "Weekly revenue",
		points: [
			5200, 3100, 4800, 2600, 4400, 5900, 3300, 4700, 6100, 3800, 5500, 4960,
		].map((value, week) => ({
			time: Date.UTC(2026, 8, 7) + week * 7 * DAY,
