		points: [61_000, 88_000, 112_000, 139_000, 168_000, 214_600].map(
			(value, index) => ({ time: Date.UTC(2021 + index, 0, 1), value })
		),
		value: "214,600",
	},
} satisfies Record<Period, unknown>;

const compactDollars = new Intl.NumberFormat("en-US", {
