	].join("\n");
	return (
		<div {...props(markdownPreviewStyles.frame)}>
			<Markdown id="release-notes">
				<ReactMarkdown
					components={markdownComponents}
					remarkPlugins={[remarkGfm]}
					remarkRehypeOptions={{ clobberPrefix: "release-notes-" }}
					skipHtml
				>
					{content}
				</ReactMarkdown>
			</Markdown>
		</div>
	);
}

