import { IconUsers, IconCalendar } from "@tabler/icons-react";

import { useState, useCallback } from "react";

function PeriodSelect<T extends string>({
	label,
	onValueChange,
	options,
	value,
}: {
	label: string;
	onValueChange: (value: T) => void;
	options: readonly T[];
	value: T;
}) {
	const choose = useCallback(
		(next: string | null) => {
			if (next !== null) {
				onValueChange(next as T);
			}
		},
		[onValueChange]
	);
	return (
		<Select onValueChange={choose} value={value}>
