				<IconCalendar aria-hidden="true" size={16} />
				<SelectValue />
			</SelectTrigger>
			<SelectPopup>
				{options.map((option) => (
					<SelectItem key={option} value={option}>
						{option}
					</SelectItem>
				))}
			</SelectPopup>
		</Select>
	);
}

const month = (index: number) => Date.UTC(2026, index, 1);

const sourceSeries = (id: string, label: string, values: number[]) => ({
	id,
