"use client";

import {
	Composer,
	ComposerActionGroup,
	ComposerActions,
	ComposerInput,
	ComposerSubmit,
	type ComposerValue,
	Suggestion,
	Suggestions,
} from "@mizen-labs/ui";

import { props, create } from "@stylexjs/stylex";

import { useCallback, useRef, useState } from "react";

const composerExampleStyles = create({
	container: {
		display: "flex",
		flexDirection: "column",
		gap: "0.5rem",
		maxWidth: "36rem",
		minWidth: 0,
		width: "100%",
	},
});

const starters = [
	"Add a dark mode toggle",
	"Fix the failing build",
	"Write tests for the form",
	"Add a loading state",
	"Find unused dependencies",
];

const WORK_MS = 2400;

export function SuggestionStarters() {
	const [value, setValue] = useState<ComposerValue>([]);
	const [working, setWorking] = useState(false);
	const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
	const send = useCallback(() => {
		setValue([]);
		setWorking(true);
		// Simulated agent work; Stop ends it early.
		clearTimeout(timer.current);
		timer.current = setTimeout(() => setWorking(false), WORK_MS);
	}, []);
	const stop = useCallback(() => {
		clearTimeout(timer.current);
		setWorking(false);
	}, []);
	return (
		<div {...props(composerExampleStyles.container)}>
			<Suggestions>
				{starters.map((starter) => (
					<Suggestion
						disabled={working}
						key={starter}
						onClick={send}
						suggestion={starter}
					/>
				))}
			</Suggestions>
			<Composer
				onStop={stop}
				onSubmit={send}
				onValueChange={setValue}
				value={value}
				working={working}
			>
				<ComposerInput
					aria-label="Message"
					placeholder="Ask the agent…"
					render={<textarea />}
				/>
				<ComposerActions>
					<ComposerActionGroup align="end">
						<ComposerSubmit />
					</ComposerActionGroup>
				</ComposerActions>
			</Composer>
		</div>
	);
}

