"use client";

import {
	Button,
	Composer,
	ComposerActionGroup,
	ComposerActions,
	ComposerInput,
	ComposerSubmit,
	Conversation,
	ConversationContent,
	ConversationEmptyState,
	ConversationFooter,
	AgentThinking,
	Message,
	StreamingText,
	type StreamingTextState,
	TaskList,
	type TaskListStep,
	Terminal,
	type TerminalStatus,
	ToolCallGroup,
	type ToolCallGroupCall,
} from "@mizen-labs/ui";

import { create, props } from "@stylexjs/stylex";

import { IconPlayerPlay } from "@tabler/icons-react";

import { useCallback, useRef, useState } from "react";

interface UserTurn {
	from: "user";
	id: string;
	text: string;
}

interface AgentTurn {
	from: "agent";
	id: string;
	plan?: { steps: readonly TaskListStep[]; title: string };
	reply?: { status: StreamingTextState; text: string };
	run?: { command: string; output: string; status: TerminalStatus };
	thinking?: { content: string; status: "complete" | "streaming" };
	tools?: readonly ToolCallGroupCall[];
}

type Turn = AgentTurn | UserTurn;

interface Scene {
	draft: string;
	turns: readonly Turn[];
	working: boolean;
}

interface Beat {
	/** Milliseconds to wait before this beat. */
	after: number;
	apply: (scene: Scene) => Scene;
}

const emptyScene: Scene = { draft: "", turns: [], working: false };

const TYPE_MS = 28;

const WORD_MS = 34;

const LINE_MS = 120;

function patchAgent(
	id: string,
	patch: (turn: AgentTurn) => Partial<AgentTurn>
): Beat["apply"] {
	return (scene) => ({
		...scene,
		turns: scene.turns.map((turn) =>
			turn.from === "agent" && turn.id === id
				? { ...turn, ...patch(turn) }
				: turn
		),
	});
}

function typing(text: string): Beat[] {
	const beats: Beat[] = [];
	for (let end = 2; end < text.length + 2; end += 2) {
		const draft = text.slice(0, end);
		beats.push({ after: TYPE_MS, apply: (scene) => ({ ...scene, draft }) });
	}
	return beats;
}

function sending(userId: string, agentId: string, after = 450): Beat {
	return {
		after,
		apply: (scene) => ({
			draft: "",
			turns: [
				...scene.turns,
				{ from: "user", id: userId, text: scene.draft },
				{ from: "agent", id: agentId },
			],
			working: true,
		}),
	};
}

function words(text: string) {
	return text
		.split(" ")
		.map((_, index, all) => all.slice(0, index + 1).join(" "));
}

function thinking(id: string, text: string): Beat[] {
	return [
		...words(text).map((content) => ({
			after: WORD_MS,
			apply: patchAgent(id, () => ({
				thinking: { content, status: "streaming" as const },
			})),
		})),
		{
			after: 500,
			apply: patchAgent(id, (turn) => ({
				thinking: {
					content: turn.thinking?.content ?? text,
					status: "complete",
				},
			})),
		},
	];
}

function planning(id: string, title: string, steps: readonly string[]): Beat {
	return {
		after: 400,
		apply: patchAgent(id, () => ({
			plan: {
				steps: steps.map((label, index) => ({
					id: `step-${index}`,
					status: "pending" as const,
					title: label,
				})),
				title,
			},
		})),
	};
}

function step(
	id: string,
	index: number,
	status: TaskListStep["status"],
	after = 300
): Beat {
	return {
		after,
		apply: patchAgent(id, (turn) => ({
			plan: turn.plan && {
				...turn.plan,
				steps: turn.plan.steps.map((item, at) =>
					at === index ? { ...item, status } : item
				),
			},
		})),
	};
}

function calling(id: string, call: ToolCallGroupCall, after = 300): Beat {
	return {
		after,
		apply: patchAgent(id, (turn) => ({
			tools: [...(turn.tools ?? []), { ...call, status: "running" }],
		})),
	};
}

function called(
	id: string,
	callId: string,
	finished: Partial<ToolCallGroupCall>,
	after = 900
): Beat {
	return {
		after,
		apply: patchAgent(id, (turn) => ({
			tools: turn.tools?.map((call) =>
				call.id === callId ? { ...call, ...finished, status: "complete" } : call
			),
		})),
	};
}

function running(id: string, command: string, lines: string[]): Beat[] {
	return [
		{
			after: 400,
			apply: patchAgent(id, () => ({
				run: { command, output: "", status: "running" },
			})),
		},
		...lines.map((_, index) => ({
			after: LINE_MS,
			apply: patchAgent(id, () => ({
				run: {
					command,
					output: lines.slice(0, index + 1).join("\n"),
					status: "running" as const,
				},
			})),
		})),
		{
			after: 500,
			apply: patchAgent(id, (turn) => ({
				run: turn.run && { ...turn.run, status: "complete" },
			})),
		},
	];
}

function replying(id: string, text: string): Beat[] {
	return [
		...words(text).map((sofar) => ({
			after: WORD_MS,
			apply: patchAgent(id, () => ({
				reply: { status: "streaming" as const, text: sofar },
			})),
		})),
		{
			after: 200,
			apply: (scene: Scene) => ({
				...patchAgent(id, (turn) => ({
					reply: { status: "complete", text: turn.reply?.text ?? text },
				}))(scene),
				working: false,
			}),
		},
	];
}

function settle(beats: readonly Beat[], from: Scene = emptyScene) {
	return beats.reduce((scene, beat) => beat.apply(scene), from);
}

function reducedMotion() {
	return matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function usePlayer(defaultBeats: readonly Beat[], start: Scene = emptyScene) {
	const [scene, setScene] = useState(start);
	const [done, setDone] = useState(false);
	const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
	const play = useCallback(
		(beats: readonly Beat[] = defaultBeats, from: Scene = start) => {
			clearTimeout(timer.current);
			setDone(false);
			if (reducedMotion()) {
				setScene(settle(beats, from));
				setDone(true);
				return;
			}
			setScene(from);
			let index = 0;
			const next = () => {
				const beat = beats[index];
				if (!beat) {
					setDone(true);
					return;
				}
				index += 1;
				setScene(beat.apply);
				timer.current = setTimeout(next, beats[index]?.after ?? 0);
			};
			timer.current = setTimeout(next, beats[0]?.after ?? 0);
		},
		[defaultBeats, start]
	);
	const watch = useCallback(
		(node: HTMLElement | null) => {
			if (!node) {
				return;
			}
			const observer = new IntersectionObserver(
				(entries) => {
					if (entries.some((entry) => entry.isIntersecting)) {
						observer.disconnect();
						play();
					}
				},
				{ threshold: 0.4 }
			);
			observer.observe(node);
			return () => {
				observer.disconnect();
				clearTimeout(timer.current);
			};
		},
		[play]
	);
	return { done, play, scene, watch };
}

function TurnView({ turn }: { turn: Turn }) {
	if (turn.from === "user") {
		return <Message from="user">{turn.text}</Message>;
	}
	return (
		<Message from="agent">
			{turn.thinking ? (
				<AgentThinking
					content={turn.thinking.content}
					status={turn.thinking.status}
				/>
			) : null}
			{turn.plan ? (
				<TaskList steps={turn.plan.steps} title={turn.plan.title} />
			) : null}
			{turn.tools ? <ToolCallGroup calls={turn.tools} /> : null}
			{turn.run ? (
				<Terminal
					command={turn.run.command}
					output={turn.run.output}
					status={turn.run.status}
				/>
			) : null}
			{turn.reply ? (
				<StreamingText content={turn.reply.text} status={turn.reply.status} />
			) : null}
		</Message>
	);
}

const conversationExampleStyles = create({
	// A bounded height: the thread scrolls inside it.
	frame: {
		blockSize: "36rem",
		display: "flex",
		flexDirection: "column",
		inlineSize: "100%",
		maxInlineSize: "48rem",
	},
	// The example and, under it, a row kept for Replay, so nothing moves
	// when it appears.
	player: {
		display: "flex",
		flexDirection: "column",
		gap: "0.5rem",
		inlineSize: "100%",
		maxInlineSize: "48rem",
	},
	replay: {
		display: "flex",
		justifyContent: "flex-end",
		minBlockSize: "2rem",
	},
});

const noop = () => undefined;

function ScriptedFooter({ scene }: { scene: Scene }) {
	return (
		<ConversationFooter>
			<Composer
				onSubmit={noop}
				onValueChange={noop}
				value={scene.draft ? [{ text: scene.draft, type: "text" }] : []}
				working={scene.working}
			>
				<ComposerInput
					aria-label="Message"
					placeholder="Ask the agent…"
					render={<textarea />}
				/>
				<ComposerActions>
					<ComposerActionGroup align="end">
						<ComposerSubmit />
					</ComposerActionGroup>
				</ComposerActions>
			</Composer>
		</ConversationFooter>
	);
}

function Replay({ done, onReplay }: { done: boolean; onReplay: () => void }) {
	return (
		<div {...props(conversationExampleStyles.replay)}>
			{done ? (
				<Button onClick={onReplay} size="sm" variant="outline">
					<IconPlayerPlay aria-hidden="true" size={16} />
					Replay
				</Button>
			) : null}
		</div>
	);
}

const DARK_MODE = "Add a dark mode toggle to the settings page.";

const SYNC = "Make it remember the choice across devices.";

const firstTurn: Beat[] = [
	...typing(DARK_MODE),
	sending("q1", "a1"),
	...thinking(
		"a1",
		"Settings lives in app/settings. Before adding a control I need to know how the theme is stored, so the toggle and the header switch never disagree."
	),
	planning("a1", "Add a dark mode toggle", [
		"Find how the theme is stored",
		"Add the toggle to settings",
		"Run the tests",
	]),
	step("a1", 0, "running"),
	calling("a1", {
		id: "read",
		input: { path: "app/layout.tsx" },
		name: "read_file",
		status: "running",
		title: "Reading app/layout.tsx",
	}),
	called("a1", "read", {
		output: 'ThemeProvider attribute="class" storageKey="theme"',
		title: "Read app/layout.tsx",
	}),
	step("a1", 0, "complete"),
	step("a1", 1, "running"),
	calling("a1", {
		id: "edit",
		input: { path: "app/settings/page.tsx" },
		name: "edit_file",
		status: "running",
		title: "Editing app/settings/page.tsx",
	}),
	called("a1", "edit", {
		output: '+ <ThemeSwitch label="Dark mode" />',
		title: "Edited app/settings/page.tsx",
	}),
	step("a1", 1, "complete"),
	step("a1", 2, "running"),
	...running("a1", "pnpm test", [
		"> vitest run",
		"",
		" ✓ settings/theme-switch.test.tsx (6 tests)",
		" ✓ settings/page.test.tsx (12 tests)",
		" ✓ layout.test.tsx (24 tests)",
		"",
		" Test Files  3 passed (3)",
		"      Tests  42 passed (42)",
	]),
	step("a1", 2, "complete"),
	...replying(
		"a1",
		"Added a Dark mode switch to Settings. It reads and writes the same theme key as the header switch, so the two stay in step, and it follows the system setting until someone picks one. All 42 tests pass."
	),
];

const secondTurn: Beat[] = [
	...typing(SYNC),
	sending("q2", "a2", 900),
	...thinking(
		"a2",
		"The theme is in localStorage, which stays on one device. Preferences already sync through the account, so the choice belongs there."
	),
	calling("a2", {
		id: "prefs",
		input: { path: "lib/preferences.ts" },
		name: "read_file",
		status: "running",
		title: "Reading lib/preferences.ts",
	}),
	called("a2", "prefs", {
		output: "export const preferences = { language, density }",
		title: "Read lib/preferences.ts",
	}),
	calling("a2", {
		id: "save",
		input: { path: "lib/preferences.ts" },
		name: "edit_file",
		status: "running",
		title: "Editing lib/preferences.ts",
	}),
	called("a2", "save", {
		output: '+ theme: "system" | "light" | "dark"',
		title: "Edited lib/preferences.ts",
	}),
	...replying(
		"a2",
		"The choice now saves to the account's preferences next to language and density, so it follows the person to every device. On a device that has never synced, it still starts from the system setting."
	),
];

